Chapter 15 SQL Structured Query Language | 96

And a Few More Relation Definitions
• create table student (
ID varchar(5), name varchar(20) not null, dept_name varchar(20), tot_cred numeric(3,0), primary key (ID), foreign key (dept_name) references department);
• create table takes (
ID varchar(5), course_id varchar(8), sec_id varchar(8), semester varchar(6), year numeric(4,0), grade varchar(2), primary key (ID, course_id, sec_id, semester, year) , foreign key (ID) references student, foreign key (course_id, sec_id, semester, year) references section);

And more still
• create table course (
course_id varchar(8), title varchar(50), dept_name varchar(20), credits numeric(2,0), primary key (course_id), foreign key (dept_name) references department);

Aggregate Functions – Group By
• Find the average salary of instructors in each department
• select dept_name, avg (salary) as avg_salary from instructor group by dept_name;

Aggregation (Cont.)
• Attributes in select clause outside of aggregate functions must appear in group by list
• /* erroneous query */ select dept_name, ID, avg (salary) from instructor group by dept_name;

Set Comparison – “some” Clause
• Find names of instructors with salary greater than that of some (at least one) instructor in the Biology department.
select distinct T.name from instructor as T, instructor as S where T.salary > S.salary and S.dept name = 'Biology';
• Same query using > some clause
select name from instructor where salary > some (select salary
from instructor where dept name = 'Biology');

Insertion
• Add a new tuple to course
insert into course
values ('CS-437', 'Database Systems', 'Comp. Sci.', 4);
• or equivalently
insert into course (course_id, title, dept_name, credits)
values ('CS-437', 'Database Systems', 'Comp. Sci.', 4);
• Add a new tuple to student with tot_creds set to null
insert into student
